const hints:Record<string,string>={'农奴':'土地束缚身份，手艺与赎身可能打开出路。','自由农民':'依靠土地与劳动，熟悉村庄共同体。','城市贫民':'资源有限，但市井消息灵通。','工匠家庭':'从工具和工坊中认识世界。','商人家庭':'契约与货单，是日常生活的一部分。','低阶贵族':'身份带来礼仪与责任，不自动授予封地。','大贵族旁支':'家名能打开一些门，个人财富仍需积累。','骑士家庭':'重视训练、誓言与军事义务。','教会孤儿':'由修会照料，认识慈善与学问。','魔法世家':'熟悉魔法传统，法术仍需亲自学习。','边境猎户':'与森林相伴，懂得准备与耐心。','田间劳动':'在土地与节气中长大，熟悉劳作与生存。','工坊学艺':'从工具和炉火中认识手艺，锻造入门。','商铺算账':'数字与货单早早进入生活，贸易入门。','教会识字':'钟声与书页相伴，识字起步。','骑士启蒙':'从小练习队列与剑术，纪律入心。','山林求生':'熟悉林间道路与采集，生存起步。','坚毅':'意志更加坚定，逆境中不易放弃。','好奇':'求知欲推动你留意细节。','谨慎':'习惯先观察再行动。','亲和':'与人相处更自然。','果敢':'面对挑战更少犹豫。','务实':'脚踏实地，生活优先。','未显现':'以太尚未回应你，普通道路同样辽阔。','微弱共鸣':'偶尔能感到微弱的以太气息。','罕见亲和':'以太与你亲近，魔法之门为你打开。','帮助邻人收获':'学会合作与生存。','捡到残缺旧书':'识字与求知由此开始。','随商队远行':'见过道路与人群，贸易有所领悟。','在森林中迷路':'在恐惧中学到方向与生存。','照料患病亲人':'懂得照顾与耐心，医术入门。','旁观骑士比武':'剑术与礼仪的种子就此埋下。','安稳生活，守护家庭':'家人与安稳，是最大的财富。','成为受人尊敬的匠人':'以手艺立身，赢得尊重。','建立自己的商号':'让名字写在货单与契约上。','探索被遗忘的遗迹':'地图之外，仍有未解之事。','成为受封骑士':'用功绩与誓言换取封号。','理解以太的秘密':'追寻低魔世界中隐秘的微光。'};
function Meter({label,value,max=100}:{label:string,value:number,max?:number}){return <div className="meter"><div><span>{label}</span><b>{Math.round(value)}<small> / {max}</small></b></div><div className="track"><i style={{width:Math.max(0,Math.min(100,max?value/max*100:0))+'%'}}/></div></div>}
