 function slotPicker(){return <div className="slot-picker"><p className="muted">每份人生独立保存，切换不会覆盖其他存档。</p>{slots.length?slots.slice().reverse().map(slot=><div className={'slot-card '+(activeId===slot.id?'current':'')} key={slot.id}><div><b>{slot.label}</b><small>{slot.game.draft.name} · {age(slot.game)}岁 · {slot.game.mode}</small><small>{date(slot.game.day)} · {regions[slot.game.region].town}</small><small>{slot.updated} · {slot.history.length}步可撤回</small></div><button disabled={activeId===slot.id&&!!game} onClick={()=>loadSlot(slot)}>{activeId===slot.id&&game?'当前人生':'读取'}</button></div>):<div className="empty"><p>还没有存档，完成角色创建后会自动保存。</p></div>}</div>}
