 useEffect(()=>{const context=(document as unknown as {modelContext?:{registerTool:(x:unknown,o:unknown)=>Promise<void>|void}}).modelContext;if(!context)return;const lifecycle=new AbortController();try{Promise.resolve(context.registerTool({name:'read_life_state',description:'读取当前人物与可选行动，不推进时间。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>{const g=ref.current;return g?{name:g.draft.name,date:date(g.day),cash:g.cash,event:g.event,alive:!g.dead,actions:g.event?events.find(e=>e.id===g.event)?.choices.map((c,i)=>({index:i,label:c.label})):['work','rest','explore']}: {status:'角色尚未创建'}}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(context.registerTool({name:'perform_life_action',description:'执行工作、休息、探索或眼前事件选项；会推进世界并保存结果。',inputSchema:{type:'object',properties:{action:{type:'string',enum:['work','rest','explore','event']},choice:{type:'integer',minimum:0,maximum:5}},required:['action'],additionalProperties:false},execute:(input:unknown)=>{const v=input as {action:string,choice?:number};if(!v||!['work','rest','explore','event'].includes(v.action))return {error:'无效行动'};if(v.action==='event'&&!Number.isInteger(v.choice))return {error:'事件需要选项编号'};return act(v.action,String(v.choice??''));}},{signal:lifecycle.signal})).catch(()=>{})}catch{}return ()=>lifecycle.abort()},[]);
 function next(){const k=steps[step].key;if(step===3&&!name.trim()){setNotice('请写下角色名字。');return}if(step!==3&&!choice){setNotice('请选择一项。');return}const d:Draft={...draft,[k]:step===3?name.trim()+' · '+gender:choice,...(step===3?{name:name.trim(),gender}: {})};setDraft(d);setNotice('');if(step===11){const g=createGame(d,mode);ref.current=g;setGame(g);setActiveId(g.id);setHistory([]);historyRef.current=[];setPanel('');}else{setStep(step+1);setChoice(d[steps[step+1].key]||'')}}
