 const battleView=(g:Game)=>{const b=g.battle;if(!b||b.done)return null;const dg=b.dungeonId==='ambush'?null:(dungeons.find(d=>d.id===b.dungeonId)||dungeons[0]);const m=dg?(b.stage>=dg.stages.length?dg.boss:dg.stages[b.stage]):null;return <div className="combat"><div className="combat-head"><div><small>{dg?`${dg.name} · ${b.stage>=dg.stages.length?'最终首领':'第'+(b.stage+1)+'关'}`:'路遇之敌 · 遭遇战'}</small><h3>{b.mname||(m&&m.name)}</h3></div><Meter label="对手生命" value={b.hp} max={b.maxHp}/></div><div className="player-stats"><Meter label="生命" value={g.hp} max={maxHp(g)}/><Meter label="体力" value={g.stamina} max={maxStamina(g)}/><Meter label="精神" value={g.spirit} max={maxSpirit(g)}/><Meter label="魔力" value={g.mana} max={effectiveMaxMana(g)}/></div><div className="combat-log">{b.log.slice(-12).map((l,i)=><p key={i}>{l}</p>)}</div><div className="combat-actions"><button className="primary" onClick={()=>act('battle','attack')}>普通攻击</button>{(jobs[g.job].moves||[]).map((m,i)=>moveUnlocked(g,g.job,i)?<button key={i} onClick={()=>act('battle','skill:'+i)}>{m[0]}</button>:null)}{['止血草','疗伤绷带','生命药水','魔力药水','大瓶魔力药水','圣水'].filter(n=>g.items.some(it=>it.name===n&&it.count>0)).map(n=><button key={n} onClick={()=>act('battle','item:'+n)}>使用{n}</button>)}<button onClick={()=>act('battle','flee')}>撤退</button></div><p className="muted">战斗不消耗时间 · 绝技消耗体力/魔力 · 每关胜利恢复三成生命</p></div>};
const battleResultView=(g:Game)=>{const b=g.battle;if(!b||!b.done)return null;return <><div className="description"><small>冒险结束</small><h3>{b.won?'凯旋而归':'未能凯旋'}</h3><p>{b.won?'你带着战利品与经验走出副本，可以再次挑战。':'你退出了副本，或失去了意识被抬回。整理好状态再来吧。'}</p></div>{b.won&&b.drop&&(()=>{const gg=gearByName(b.drop||'');return <div className="estate-card drop-card"><h3>战利品 · {b.drop} {gg&&<em className={'qtag q'+gearQuality(gg.price)}>{qualityName[gearQuality(gg.price)]}</em>}</h3>{gg&&<p className="muted">{gg.slot} · {gearDesc(gg.name)||'无属性'} · {gg.desc}</p>}<p className="muted">已收入背包，可在背包中穿戴或售出。</p></div>})()}<div className="combat-actions battle-result-actions">{g.hosting?.active&&b.won&&<><button className="primary" onClick={()=>{act('battle-continue');setPanel('模拟');setTimeout(()=>window.dispatchEvent(new CustomEvent('verilann:start-sim')),0)}}>继续模拟</button><button onClick={()=>{act('battle-recover');setPanel('模拟');setTimeout(()=>window.dispatchEvent(new CustomEvent('verilann:start-sim')),0)}}>恢复至最佳状态后继续</button><button onClick={()=>{act('battle-exit');setPanel('模拟')}}>退出模拟</button><span className="sep"/></>}<button className="primary" onClick={()=>act('endbattle')}>收拾行囊，离开副本</button></div></>};
