        const inheritTxt=j.attrStep?(i===16?'继承全部进阶职业（含实际等级成长，50级封顶）':(j.req?.map(([id])=>jobs[id].name).join(' + ')||'')):'';
        const stepTxt=j.attrStep?attrNames.filter(a=>j.attrStep![a]).map(a=>a+' +'+j.attrStep![a]+'/级').join(' · '):'';
        const jobSkTxt=i===16?'全职业技能（所有技能皆可修炼）':(j.jobSkills?.join(' · ')||'');
        const payTxt=j.payStep?'日薪 '+Math.round(j.base+(j.payStep?rk*j.payStep:0))+'铜（每10级 +'+Math.round(j.payStep*10)+'铜）':('基础日薪'+j.base+'铜');
